 75→/// Options for running a workflow.
 76→#[derive(Debug, Default)]
 77→pub struct RunOptions {
 78→    /// Workflow name (defaults to "default").
 79→    pub workflow: Option<String>,
 80→    /// Only run these steps.
 81→    pub only: HashSet<String>,
 82→    /// Skip these steps.
 83→    pub skip: HashSet<String>,
 84→    /// How to handle skipped step dependencies.
 85→    pub skip_behavior: SkipBehavior,
 86→    /// Force re-run these steps even if complete.
 87→    pub force: HashSet<String>,
 88→    /// Dry run mode.
 89→    pub dry_run: bool,
 90→    /// Requirements that are provided by the environment and should skip gap checks.
 91→    pub provided_requirements: HashSet<String>,
 92→    /// Active environment name for only_environments filtering.
 93→    pub active_environment: Option<String>,
 94→}
