200→/// A prompt to show to the user.
201→#[derive(Debug, Clone)]
202→pub struct Prompt {
203→    /// Unique key for the prompt (used for caching/lookup).
204→    pub key: String,
205→    /// The question to display.
206→    pub question: String,
207→    /// The type of prompt.
208→    pub prompt_type: PromptType,
209→    /// Default value if user just presses enter.
210→    pub default: Option<String>,
211→}
212→
213→/// The type of prompt.
214→#[derive(Debug, Clone)]
215→pub enum PromptType {
216→    /// Yes/no confirmation.
217→    Confirm,
218→    /// Free-form text input.
219→    Input,
220→    /// Select one from a list of options.
221→    Select { options: Vec<PromptOption> },
222→    /// Select multiple from a list of options.
223→    MultiSelect { options: Vec<PromptOption> },
224→}
225→
226→/// An option in a select prompt.
227→#[derive(Debug, Clone)]
228→pub struct PromptOption {
229→    /// Display label.
230→    pub label: String,
231→    /// Value returned when selected.
232→    pub value: String,
233→}
234→
235→/// Result of a prompt.
236→#[derive(Debug, Clone)]
237→pub enum PromptResult {
238→    /// Boolean result from confirm.
239→    Bool(bool),
240→    /// String result from input or select.
241→    String(String),
242→    /// Multiple string results from multi-select.
243→    Strings(Vec<String>),
244→}
245→
246→impl PromptResult {
247→    /// Get as string, suitable for interpolation.
248→    pub fn as_string(&self) -> String {
249→        match self {
250→            Self::Bool(b) => b.to_string(),
251→            Self::String(s) => s.clone(),
252→            Self::Strings(v) => v.join(","),
253→        }
254→    }
255→
256→    /// Get as bool if this is a Bool result.
257→    pub fn as_bool(&self) -> Option<bool> {
258→        match self {
259→            Self::Bool(b) => Some(*b),
260→            _ => None,
261→        }
262→    }
263→}
