  1→//! Dependency graph for step execution ordering.
  2→
  3→use std::collections::{HashMap, HashSet, VecDeque};
  4→
  5→use crate::error::{BivvyError, Result};
  6→
  7→/// How to handle skipping a step that has dependents.
  8→#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
  9→pub enum SkipBehavior {
 10→    /// Skip the step and all its dependents.
 11→    #[default]
 12→    SkipWithDependents,
 13→    /// Don't skip - run the step anyway.
 14→    RunAnyway,
 15→    /// Skip only this step, attempt to run dependents.
 16→    SkipOnly,
 17→}
 18→
 19→/// Represents the dependency relationships between steps.
 20→#[derive(Debug, Clone)]
 21→pub struct DependencyGraph {
 22→    /// Map of step name to its direct dependencies.
 23→    dependencies: HashMap<String, HashSet<String>>,
 24→    /// Map of step name to steps that depend on it.
 25→    dependents: HashMap<String, HashSet<String>>,
 26→    /// All step names in the graph.
 27→    steps: HashSet<String>,
 28→}
 29→
 30→impl DependencyGraph {
 31→    /// Create a new dependency graph builder.
 32→    pub fn builder() -> DependencyGraphBuilder {
 33→        DependencyGraphBuilder::new()
 34→    }
 35→
 36→    /// Get the direct dependencies of a step.
 37→    pub fn dependencies_of(&self, step: &str) -> Option<&HashSet<String>> {
 38→        self.dependencies.get(step)
 39→    }
 40→
 41→    /// Get steps that depend on the given step.
 42→    pub fn dependents_of(&self, step: &str) -> Option<&HashSet<String>> {
 43→        self.dependents.get(step)
 44→    }
 45→
 46→    /// Check if a step exists in the graph.
 47→    pub fn contains(&self, step: &str) -> bool {
 48→        self.steps.contains(step)
 49→    }
 50→
 51→    /// Get all step names.
 52→    pub fn steps(&self) -> &HashSet<String> {
 53→        &self.steps
 54→    }
 55→
 56→    /// Get the number of steps in the graph.
 57→    pub fn len(&self) -> usize {
 58→        self.steps.len()
 59→    }
 60→
 61→    /// Check if the graph is empty.
 62→    pub fn is_empty(&self) -> bool {
 63→        self.steps.is_empty()
 64→    }
 65→
 66→    /// Returns steps in topological order (dependencies before dependents).
 67→    ///
 68→    /// Returns an error if a cycle is detected.
 69→    pub fn topological_order(&self) -> Result<Vec<String>> {
 70→        // Count incoming edges for each node
 71→        let mut in_degree: HashMap<String, usize> = HashMap::new();
 72→        for step in &self.steps {
 73→            in_degree.insert(
 74→                step.clone(),
 75→                self.dependencies.get(step).map_or(0, |d| d.len()),
 76→            );
 77→        }
 78→
 79→        // Start with nodes that have no dependencies
 80→        let mut queue: VecDeque<String> = in_degree
 81→            .iter()
 82→            .filter(|(_, &degree)| degree == 0)
 83→            .map(|(step, _)| step.clone())
 84→            .collect();
 85→
 86→        let mut result = Vec::with_capacity(self.steps.len());
 87→
 88→        while let Some(step) = queue.pop_front() {
 89→            result.push(step.clone());
 90→
 91→            // Reduce in-degree for all dependents
 92→            if let Some(dependents) = self.dependents.get(&step) {
 93→                for dependent in dependents {
 94→                    if let Some(degree) = in_degree.get_mut(dependent) {
 95→                        *degree -= 1;
 96→                        if *degree == 0 {
 97→                            queue.push_back(dependent.clone());
 98→                        }
 99→                    }
100→                }

  1→//! Detection aggregation and ordering.
  2→
  3→use std::path::Path;
  4→
  5→use super::{
  6→    conflicts::{Conflict, ConflictDetector},
  7→    package_manager::{PackageManager, PackageManagerDetection, PackageManagerDetector},
  8→    project::{ProjectDetection, ProjectDetector},
  9→};
 10→
 11→/// Aggregates all detection results.
 12→#[derive(Debug)]
 13→pub struct FullDetection {
 14→    pub project: ProjectDetection,
 15→    pub package_managers: PackageManagerDetection,
 16→    pub conflicts: Vec<Conflict>,
 17→    pub suggested_templates: Vec<SuggestedTemplate>,
 18→}
 19→
 20→/// A suggested template from detection.
 21→#[derive(Debug, Clone)]
 22→pub struct SuggestedTemplate {
 23→    pub name: String,
 24→    pub category: String,
 25→    pub reason: String,
 26→    pub priority: u32,
 27→}
 28→
 29→/// Runs all detectors and aggregates results.
 30→pub struct DetectionRunner;
 31→
 32→impl DetectionRunner {
 33→    /// Run all detectors on a project.
 34→    pub fn run(project_root: &Path) -> FullDetection {
 35→        let project = ProjectDetector::detect(project_root);
 36→        let package_managers = PackageManagerDetector::detect(project_root);
 37→        let conflicts = ConflictDetector::detect(project_root);
 38→
 39→        let suggested_templates = Self::suggest_templates(&project, &package_managers);
 40→
 41→        FullDetection {
 42→            project,
 43→            package_managers,
 44→            conflicts,
 45→            suggested_templates,
 46→        }
 47→    }
 48→
 49→    fn suggest_templates(
 50→        project: &ProjectDetection,
 51→        pm: &PackageManagerDetection,
 52→    ) -> Vec<SuggestedTemplate> {
 53→        let mut suggestions = Vec::new();
 54→
 55→        // System package manager (priority 10)
 56→        if let Some(ref system_pm) = pm.system {
 57→            let (name, category) = match system_pm {
 58→                PackageManager::Homebrew => ("brew", "system"),
 59→                PackageManager::Chocolatey => ("chocolatey", "windows"),
 60→                PackageManager::Apt => ("apt", "system"),
 61→                PackageManager::Yum => ("yum", "system"),
 62→                PackageManager::Pacman => ("pacman", "system"),
 63→                _ => ("unknown", "system"),
 64→            };
 65→
 66→            suggestions.push(SuggestedTemplate {
 67→                name: name.to_string(),
 68→                category: category.to_string(),
 69→                reason: "System package manager detected".to_string(),
 70→                priority: 10,
 71→            });
 72→        }
 73→
 74→        // Version manager (priority 20)
 75→        if let Some(ref vm) = pm.version_manager {
 76→            let name = match vm {
 77→                PackageManager::Mise => "mise",
 78→                PackageManager::Asdf => "asdf",
 79→                PackageManager::Volta => "volta",
 80→                _ => "unknown",
 81→            };
 82→
 83→            suggestions.push(SuggestedTemplate {
 84→                name: name.to_string(),
 85→                category: "version_manager".to_string(),
 86→                reason: format!("{:?} detected", vm),
 87→                priority: 20,
 88→            });
 89→        }
 90→
 91→        // Language templates from project detection (priority 30)
 92→        for detail in &project.details {
 93→            if let Some(ref template) = detail.suggested_template {
 94→                suggestions.push(SuggestedTemplate {
 95→                    name: template.clone(),
 96→                    category: "language".to_string(),
 97→                    reason: detail.details.first().cloned().unwrap_or_default(),
 98→                    priority: 30,
 99→                });
100→            }
101→        }
102→
103→        // Sort by priority
104→        suggestions.sort_by_key(|s| s.priority);
105→
106→        suggestions
107→    }
108→}
