  1→//! Interactive recovery for step failures.
  2→//!
  3→//! When a step fails during `bivvy run`, this module provides a recovery menu
  4→//! allowing the user to retry, fix, skip, open a debug shell, enter a custom
  5→//! fix command, or abort.
  6→
  7→use std::collections::HashMap;
  8→use std::path::Path;
  9→
 10→use crate::error::Result;
 11→use crate::shell::{execute, CommandOptions};
 12→use crate::ui::{Prompt, PromptOption, PromptType, UserInterface};
 13→
 14→use super::patterns::FixSuggestion;
 15→
 16→/// Recovery action chosen by the user.
 17→#[derive(Debug, Clone, PartialEq, Eq)]
 18→pub enum RecoveryAction {
 19→    /// Re-execute the step.
 20→    Retry,
 21→    /// Run the suggested fix command, then re-execute.
 22→    Fix(String),
 23→    /// Run a user-entered custom fix command, then re-execute.
 24→    CustomFix(String),
 25→    /// Skip this step and continue.
 26→    Skip,
 27→    /// Open a debug shell, then return to the recovery menu.
 28→    Shell,
 29→    /// Stop the workflow.
 30→    Abort,
 31→}
 32→
 33→/// Prompt the user for a recovery action after a step failure.
 34→///
 35→/// Returns the chosen action. The `fix` parameter controls whether a Fix
 36→/// option appears in the menu. The `has_hint` flag indicates a low-confidence
 37→/// match exists, which adds a "Fix (custom)" option for the user to enter
 38→/// their own command.
 39→pub fn prompt_recovery(
 40→    ui: &mut dyn UserInterface,
 41→    step_name: &str,
 42→    fix: Option<&FixSuggestion>,
 43→    has_hint: bool,
 44→) -> Result<RecoveryAction> {
 45→    let mut options = vec![PromptOption {
 46→        label: "Retry".to_string(),
 47→        value: "retry".to_string(),
 48→    }];
 49→
 50→    if let Some(f) = fix {
 51→        options.push(PromptOption {
 52→            label: format!("Fix — {}", f.label),
 53→            value: "fix".to_string(),
 54→        });
 55→    }
 56→
 57→    if has_hint {
 58→        options.push(PromptOption {
 59→            label: "Fix (custom) — enter your own command".to_string(),
 60→            value: "custom_fix".to_string(),
 61→        });
 62→    }
 63→
 64→    options.push(PromptOption {
 65→        label: "Skip".to_string(),
 66→        value: "skip".to_string(),
 67→    });
 68→
 69→    options.push(PromptOption {
 70→        label: "Shell".to_string(),
 71→        value: "shell".to_string(),
 72→    });
 73→
 74→    options.push(PromptOption {
 75→        label: "Abort".to_string(),
 76→        value: "abort".to_string(),
 77→    });
 78→
 79→    let prompt = Prompt {
 80→        key: format!("recovery_{}", step_name),
 81→        question: "How do you want to proceed?".to_string(),
 82→        prompt_type: PromptType::Select { options },
 83→        default: Some("retry".to_string()),
 84→    };
