200→/// A prompt to show to the user.
201→#[derive(Debug, Clone)]
202→pub struct Prompt {
203→    /// Unique key for the prompt (used for caching/lookup).
204→    pub key: String,
205→    /// The question to display.
206→    pub question: String,
207→    /// The type of prompt.
208→    pub prompt_type: PromptType,
