  1→//! Mock UI implementation for testing.
  2→//!
  3→//! `MockUI` implements the `UserInterface` trait and captures all
  4→//! interactions for later assertion. It can be configured with
  5→//! pre-determined prompt responses.
  6→//!
  7→//! # Example
  8→//!
  9→//! ```
 10→//! use bivvy::ui::{MockUI, OutputMode, Prompt, PromptType, UserInterface};
 11→//!
 12→//! let mut ui = MockUI::new();
 13→//! ui.set_prompt_response("db_name", "myapp_dev");
 14→//!
 15→//! // Use ui in code under test...
 16→//! ui.message("Starting setup");
 17→//! ui.success("Done!");
 18→//!
 19→//! // Assert on captured interactions
 20→//! assert!(ui.messages().contains(&"Starting setup".to_string()));
 21→//! assert!(ui.successes().contains(&"Done!".to_string()));
 22→//! ```
 23→
 24→use std::collections::{HashMap, VecDeque};
 25→
 26→use crate::error::Result;
 27→
 28→use super::{
 29→    OutputMode, Prompt, PromptResult, PromptType, RunSummary, SpinnerHandle, UserInterface,
 30→};
 31→
 32→/// Mock UI implementation for testing.
 33→///
 34→/// Captures all UI interactions and allows pre-configured prompt responses.
 35→/// Supports both single responses (via `set_prompt_response`) and queued
 36→/// responses (via `queue_prompt_responses`) for keys called multiple times.
 37→#[derive(Debug, Default)]
 38→pub struct MockUI {
 39→    mode: OutputMode,
 40→    interactive: bool,
 41→    messages: Vec<String>,
 42→    successes: Vec<String>,
 43→    warnings: Vec<String>,
 44→    errors: Vec<String>,
 45→    headers: Vec<String>,
 46→    hints: Vec<String>,
 47→    progress: Vec<(usize, usize)>,
 48→    spinners: Vec<String>,
 49→    run_headers: Vec<(String, String, usize, String)>,
 50→    error_blocks: Vec<(String, String, Option<String>)>,
 51→    summaries: Vec<RunSummary>,
 52→    prompt_responses: HashMap<String, String>,
 53→    prompt_queues: HashMap<String, VecDeque<String>>,
 54→    prompts_shown: Vec<String>,
 55→    /// Fallback response for any prompt key not in `prompt_responses` or `prompt_queues`.
 56→    default_prompt_response: Option<String>,
 57→}
 58→
 59→impl MockUI {
 60→    /// Create a new MockUI with Normal output mode.
 61→    pub fn new() -> Self {
 62→        Self {
 63→            mode: OutputMode::Normal,
 64→            ..Default::default()
 65→        }
 66→    }
 67→
 68→    /// Create a new MockUI with a specific output mode.
 69→    pub fn with_mode(mode: OutputMode) -> Self {
 70→        Self {
 71→            mode,
 72→            ..Default::default()
 73→        }
 74→    }
 75→
 76→    /// Set a response for a prompt key.
 77→    ///
 78→    /// When `prompt()` is called with this key, it returns the configured response.
 79→    pub fn set_prompt_response(&mut self, key: &str, response: &str) {
 80→        self.prompt_responses
 81→            .insert(key.to_string(), response.to_string());
 82→    }
 83→
 84→    /// Set multiple prompt responses at once.
 85→    pub fn with_prompt_responses(mut self, responses: HashMap<String, String>) -> Self {
 86→        self.prompt_responses = responses;
 87→        self
 88→    }
 89→
 90→    /// Queue multiple responses for the same prompt key.
 91→    ///
 92→    /// Responses are returned in order. After the queue is exhausted,
 93→    /// falls back to `set_prompt_response` or defaults.
 94→    pub fn queue_prompt_responses(&mut self, key: &str, responses: Vec<&str>) {
 95→        let queue = responses.into_iter().map(|s| s.to_string()).collect();
 96→        self.prompt_queues.insert(key.to_string(), queue);
 97→    }
 98→
 99→    /// Set a default response for any prompt key not explicitly configured.
100→    ///
101→    /// Useful when a workflow may prompt with unpredictable keys (e.g., recovery
102→    /// prompts whose key includes the step name, which depends on template detection).
103→    pub fn set_default_prompt_response(&mut self, response: &str) {
104→        self.default_prompt_response = Some(response.to_string());
105→    }
106→
107→    /// Set whether this mock behaves as interactive.
108→    pub fn set_interactive(&mut self, interactive: bool) {
109→        self.interactive = interactive;
110→    }
111→
112→    /// Get all captured messages.
113→    pub fn messages(&self) -> &[String] {
114→        &self.messages
115→    }
116→
117→    /// Get all captured success messages.
118→    pub fn successes(&self) -> &[String] {
119→        &self.successes
120→    }
121→
122→    /// Get all captured warning messages.
123→    pub fn warnings(&self) -> &[String] {
124→        &self.warnings
125→    }
126→
127→    /// Get all captured error messages.
128→    pub fn errors(&self) -> &[String] {
129→        &self.errors
130→    }
131→
132→    /// Get all captured headers.
133→    pub fn headers(&self) -> &[String] {
134→        &self.headers
135→    }
136→
137→    /// Get all captured hints.
138→    pub fn hints(&self) -> &[String] {
139→        &self.hints
140→    }
141→
142→    /// Get all captured progress updates.
143→    pub fn progress(&self) -> &[(usize, usize)] {
144→        &self.progress
145→    }
146→
147→    /// Get all spinner messages that were started.
148→    pub fn spinners(&self) -> &[String] {
149→        &self.spinners
150→    }
151→
152→    /// Get all prompts that were shown (by key).
153→    pub fn prompts_shown(&self) -> &[String] {
154→        &self.prompts_shown
155→    }
156→
157→    /// Check if a specific message was shown.
158→    pub fn has_message(&self, msg: &str) -> bool {
159→        self.messages.iter().any(|m| m.contains(msg))
160→    }
161→
162→    /// Check if a specific success was shown.
163→    pub fn has_success(&self, msg: &str) -> bool {
164→        self.successes.iter().any(|m| m.contains(msg))
165→    }
166→
167→    /// Check if a specific error was shown.
168→    pub fn has_error(&self, msg: &str) -> bool {
169→        self.errors.iter().any(|m| m.contains(msg))
170→    }
171→
172→    /// Check if a specific hint was shown.
173→    pub fn has_hint(&self, msg: &str) -> bool {
174→        self.hints.iter().any(|m| m.contains(msg))
175→    }
176→
177→    /// Check if a specific warning was shown.
178→    pub fn has_warning(&self, msg: &str) -> bool {
179→        self.warnings.iter().any(|m| m.contains(msg))
180→    }
181→
182→    /// Get all captured run headers as (app_name, workflow, step_count, version).
183→    pub fn run_headers(&self) -> &[(String, String, usize, String)] {
184→        &self.run_headers
185→    }
186→
187→    /// Get all captured error blocks as (command, output, hint).
188→    pub fn error_blocks(&self) -> &[(String, String, Option<String>)] {
189→        &self.error_blocks
190→    }
191→
192→    /// Get all captured run summaries.
193→    pub fn summaries(&self) -> &[RunSummary] {
194→        &self.summaries
195→    }
196→
197→    /// Check if any summary was a success.
198→    pub fn has_successful_summary(&self) -> bool {
199→        self.summaries.iter().any(|s| s.success)
200→    }
201→
202→    /// Clear all captured interactions.
203→    pub fn clear(&mut self) {
204→        self.messages.clear();
205→        self.successes.clear();
206→        self.warnings.clear();
207→        self.errors.clear();
208→        self.headers.clear();
209→        self.hints.clear();
210→        self.progress.clear();
211→        self.spinners.clear();
212→        self.run_headers.clear();
213→        self.error_blocks.clear();
214→        self.summaries.clear();
215→        self.prompts_shown.clear();
216→    }
217→}
218→
219→impl UserInterface for MockUI {
220→    fn output_mode(&self) -> OutputMode {
221→        self.mode
222→    }
223→
224→    fn message(&mut self, msg: &str) {
225→        self.messages.push(msg.to_string());
226→    }
227→
228→    fn success(&mut self, msg: &str) {
229→        self.successes.push(msg.to_string());
230→    }
231→
232→    fn warning(&mut self, msg: &str) {
233→        self.warnings.push(msg.to_string());
234→    }
235→
236→    fn error(&mut self, msg: &str) {
237→        self.errors.push(msg.to_string());
238→    }
239→
240→    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
241→        self.prompts_shown.push(prompt.key.clone());
242→
243→        let is_confirm = matches!(prompt.prompt_type, PromptType::Confirm);
244→        let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
245→
246→        // Check queued responses first (for keys called multiple times)
247→        if let Some(queue) = self.prompt_queues.get_mut(&prompt.key) {
248→            if let Some(response) = queue.pop_front() {
249→                if is_confirm {
250→                    let val = matches!(response.as_str(), "true" | "yes" | "y" | "1");
251→                    return Ok(PromptResult::Bool(val));
252→                }
253→                if is_multiselect {
254→                    let values: Vec<String> =
255→                        response.split(',').map(|s| s.trim().to_string()).collect();
256→                    return Ok(PromptResult::Strings(values));
257→                }
258→                return Ok(PromptResult::String(response));
259→            }
260→        }
261→
262→        // Return pre-configured response if available
263→        if let Some(response) = self.prompt_responses.get(&prompt.key) {
264→            if is_confirm {
265→                let val = matches!(response.as_str(), "true" | "yes" | "y" | "1");
266→                return Ok(PromptResult::Bool(val));
267→            }
268→            if is_multiselect {
269→                let values: Vec<String> =
270→                    response.split(',').map(|s| s.trim().to_string()).collect();
271→                return Ok(PromptResult::Strings(values));
272→            }
273→            return Ok(PromptResult::String(response.clone()));
274→        }
275→
276→        // Fall back to default_prompt_response if set (before prompt.default)
277→        if let Some(ref response) = self.default_prompt_response {
278→            if is_confirm {
279→                let val = matches!(response.as_str(), "true" | "yes" | "y" | "1");
280→                return Ok(PromptResult::Bool(val));
281→            }
282→            if is_multiselect {
283→                let values: Vec<String> =
284→                    response.split(',').map(|s| s.trim().to_string()).collect();
285→                return Ok(PromptResult::Strings(values));
286→            }
287→            return Ok(PromptResult::String(response.clone()));
288→        }
289→
290→        // Fall back to default if available
291→        if let Some(default) = &prompt.default {
292→            if is_confirm {
293→                let val = matches!(default.as_str(), "true" | "yes" | "y" | "1");
294→                return Ok(PromptResult::Bool(val));
295→            }
296→            if is_multiselect {
297→                let values: Vec<String> =
298→                    default.split(',').map(|s| s.trim().to_string()).collect();
299→                return Ok(PromptResult::Strings(values));
300→            }
301→            return Ok(PromptResult::String(default.clone()));
302→        }
303→
304→        // Return type-appropriate empty for last resort (for testing)
305→        if is_confirm {
306→            return Ok(PromptResult::Bool(false));
307→        }
308→        if is_multiselect {
309→            return Ok(PromptResult::Strings(Vec::new()));
310→        }
311→        Ok(PromptResult::String(String::new()))
312→    }
313→
314→    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
315→        self.spinners.push(message.to_string());
316→        Box::new(MockSpinner::new())
317→    }
318→
319→    fn show_header(&mut self, title: &str) {
320→        self.headers.push(title.to_string());
321→    }
322→
323→    fn show_hint(&mut self, hint: &str) {
324→        self.hints.push(hint.to_string());
325→    }
326→
327→    fn show_progress(&mut self, current: usize, total: usize) {
328→        self.progress.push((current, total));
329→    }
330→
331→    fn show_run_header(
332→        &mut self,
333→        app_name: &str,
334→        workflow: &str,
335→        step_count: usize,
336→        version: &str,
337→    ) {
338→        self.run_headers.push((
339→            app_name.to_string(),
340→            workflow.to_string(),
341→            step_count,
342→            version.to_string(),
343→        ));
344→        self.headers.push(app_name.to_string());
345→    }
346→
347→    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>) {
348→        self.error_blocks.push((
349→            command.to_string(),
350→            output.to_string(),
351→            hint.map(|h| h.to_string()),
352→        ));
353→        self.errors.push(command.to_string());
354→        if !output.is_empty() {
355→            self.messages.push(output.to_string());
356→        }
357→        if let Some(h) = hint {
358→            self.hints.push(h.to_string());
359→        }
360→    }
361→
362→    fn show_run_summary(&mut self, summary: &RunSummary) {
363→        self.summaries.push(summary.clone());
364→        // Also delegate to the default behavior for backward compatibility
365→        if summary.success {
366→            self.successes.push(format!(
367→                "Setup complete! ({} run, {} skipped)",
368→                summary.steps_run, summary.steps_skipped
369→            ));
370→        } else {
371→            self.errors.push(format!(
372→                "Setup failed ({} run, {} failed)",
373→                summary.steps_run,
374→                summary.failed_steps.len()
375→            ));
376→        }
377→    }
378→
379→    fn is_interactive(&self) -> bool {
380→        self.interactive
381→    }
382→
383→    fn set_output_mode(&mut self, mode: OutputMode) {
384→        self.mode = mode;
385→    }
386→}
